-- Build detailed independent Cliniko training for VAs.
insert into public.training_courses (slug,title,summary,category,country_focus,estimated_minutes,recommended_order,status,content_version,trademark_disclaimer,reviewed_by,last_reviewed_at,published_at,created_at,updated_at)
values ('cliniko-for-virtual-assistants','Cliniko for Virtual Assistants','Independent Cliniko workflow training for VAs supporting allied health practices, covering patients, appointments, reminders, forms, invoices, payments, communications, permissions, and admin QA.','software','Australia',182,20,'draft',1,'Cliniko is a trademark of its respective owner. This independent course is not affiliated with, certified by, or endorsed by Cliniko. Product interfaces and features may change; verify current official Cliniko documentation.',null,null,null,now(),now())
