insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='cliniko-for-virtual-assistants'),'Cliniko Foundations','Understand patient records, permissions, and practice workflow.',1)
on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='cliniko-for-virtual-assistants') and position=1),'cliniko-practice-workflow-and-va-permissions','Cliniko Practice Workflow and VA Permissions','Cliniko supports patient records, appointments, communications, invoicing, payments, and practice administration. A VA should first understand what the practice expects them to manage and what information is clinically restricted.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand how Cliniko supports practice administration","Map VA permissions to actual responsibilities","Avoid confusing software access with clinical authority"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Cliniko supports patient records, appointments, communications, invoicing, payments, and practice administration. A VA should first understand what the practice expects them to manage and what information is clinically restricted."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Appointments link patients, practitioners, business locations, appointment types, and billing context.","Permissions can restrict financial or other information.","Practice settings affect reminders, invoices, communications, and workflows.","Software access should follow minimum necessary permissions.","Clinical notes and practitioner decisions remain outside routine VA editing."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the practice''s Cliniko roles and permissions.","Map appointment types and practitioners.","Identify approved patient-admin tasks.","Identify billing tasks and approval boundaries.","Learn where forms, reminders, invoices, and communications are managed.","Document escalation for clinical, privacy, billing, or complaint issues."]},{"type":"callout","title":"Stay inside the role","text":"Do not request broader Cliniko access simply for convenience. Use the least privilege needed, and never edit clinical records unless that is explicitly part of a qualified, authorized role."},{"type":"callout","title":"Keep this current","text":"Cliniko changes over time. Verify the current official Cliniko Help before publishing or reviewing this lesson, especially appointment, reminder, invoice, payment, permission, and integration workflows."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using one shared login","Assuming administrator access means permission to change everything","Editing a clinical note to fix wording","Changing practice-wide settings without approval","Learning Cliniko without learning the clinic''s process"]},{"type":"scenario","title":"Practice scenario","text":"You can see patient records, invoices, and settings, but your role is scheduling and reminder administration only. Explain which parts you should use and which you should leave alone."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Permissions should match role.","Practice process comes first.","Clinical data is not routine admin content.","Settings changes need authority."]}]'::jsonb,26,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='cliniko-for-virtual-assistants') and position=1),'patient-records-forms-and-administrative-data-quality','Patient Records, Forms, and Administrative Data Quality','Patient records drive appointments, reminders, invoices, and communication. Duplicate or incorrect records can expose private data or create billing errors.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Maintain clean patient admin records","Handle forms and documents safely","Resolve duplicates and missing data without guessing"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Patient records drive appointments, reminders, invoices, and communication. Duplicate or incorrect records can expose private data or create billing errors."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Identity resolution should use the practice''s approved checks.","Administrative data and clinical data have different editing boundaries.","Forms may contain sensitive information.","Communication preferences matter.","Duplicate records should be resolved carefully rather than merged from assumptions."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Search before creating a patient.","Verify approved identity fields.","Update administrative details only from reliable source information.","Attach forms and documents to the correct patient.","Respect communication preferences.","Flag duplicate or conflicting records for safe resolution.","Document significant changes if the practice requires it."]},{"type":"callout","title":"Stay inside the role","text":"Do not alter health history, diagnoses, clinical notes, or practitioner-authored information to clean up the record."},{"type":"callout","title":"Keep this current","text":"Cliniko changes over time. Verify the current official Cliniko Help before publishing or reviewing this lesson, especially appointment, reminder, invoice, payment, permission, and integration workflows."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Creating duplicates from spelling differences","Uploading a form to the wrong patient","Changing clinical information from an email","Ignoring communication preferences","Using exported patient data outside approved systems"]},{"type":"scenario","title":"Practice scenario","text":"Two Cliniko patient records have the same name and mobile number but different dates of birth. Explain how you investigate without merging them prematurely."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Identity first.","Keep admin and clinical data boundaries clear.","Respect communication settings.","Avoid destructive cleanup."]}]'::jsonb,26,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

