insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='cliniko-for-virtual-assistants') and position=2),'appointments-appointment-types-and-practitioner-calendars','Appointments, Appointment Types, and Practitioner Calendars','Cliniko appointments can contain practitioner, patient, business location, date, time, and appointment-type information. Correct setup matters for reminders, billing, and practitioner workflows.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Book the correct appointment in Cliniko","Use appointment type and practitioner rules","Handle cancellations and changes safely"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Cliniko appointments can contain practitioner, patient, business location, date, time, and appointment-type information. Correct setup matters for reminders, billing, and practitioner workflows."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Appointment type can affect duration and reminder settings.","Practitioner availability and location matter.","Online and internally created bookings may trigger different notifications or settings.","Changes should preserve patient context.","Clinical triage still belongs to practitioners."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify the approved appointment type.","Select the correct practitioner and location.","Confirm patient details and time.","Check referral/form requirements if the practice uses them.","Create or update the appointment.","Send or verify confirmation according to settings.","Record cancellation or no-show outcome under practice rules."]},{"type":"callout","title":"Stay inside the role","text":"Do not choose a clinical appointment type based on your own assessment of symptoms."},{"type":"callout","title":"Keep this current","text":"Cliniko changes over time. Verify the current official Cliniko Help before publishing or reviewing this lesson, especially appointment, reminder, invoice, payment, permission, and integration workflows."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Selecting the wrong location","Changing appointment duration to fit a gap","Booking the wrong practitioner","Assuming online booking settings cover every appointment type","Failing to record cancellation reason where required"]},{"type":"scenario","title":"Practice scenario","text":"A patient wants a shorter appointment because they are busy. The requested type is not normally used for initial visits. Explain how you handle the Cliniko booking without changing clinical workflow yourself."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use approved appointment types.","Check practitioner and location.","Do not use the calendar to make clinical decisions.","Keep changes visible."]}]'::jsonb,26,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='cliniko-for-virtual-assistants') and position=2),'confirmations-sms-and-email-reminders-and-follow-up-messages','Confirmations, SMS and Email Reminders, and Follow-Up Messages','Cliniko supports appointment confirmations and email or SMS reminders linked to appointment types and business settings. Automations are only as reliable as their templates, configuration, patient data, and exceptions.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand reminder template logic","Respect patient communication preferences","QA automated messages before relying on them"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Cliniko supports appointment confirmations and email or SMS reminders linked to appointment types and business settings. Automations are only as reliable as their templates, configuration, patient data, and exceptions."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Reminder templates need to be attached to appointment types to send as expected.","Business/location settings can affect whether reminders run.","SMS reminders require a mobile number and can be affected by communication preferences.","Cancellations or reschedules should change what communication is appropriate.","Automated messages may include sensitive appointment context, so wording should be reviewed."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm the practice-approved reminder cadence.","Check templates for correct business and appointment wording.","Verify templates are linked to intended appointment types.","Respect patient channel preferences.","Test changes safely before wide use.","Review failed or unexpected reminders.","Stop or adjust communication when appointment status changes."]},{"type":"callout","title":"Stay inside the role","text":"Do not override a patient''s communication preference to improve attendance metrics."},{"type":"callout","title":"Keep this current","text":"Cliniko changes over time. Verify the current official Cliniko Help before publishing or reviewing this lesson, especially appointment, reminder, invoice, payment, permission, and integration workflows."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Creating a template but not linking it","Using one reminder for clinically different appointment types","Sending SMS to a patient who opted out","Forgetting business or location settings","Assuming automation succeeded without checking exceptions"]},{"type":"scenario","title":"Practice scenario","text":"Patients with one appointment type are not receiving reminders, while other appointment types work. Describe the configuration checks you make before manually messaging everyone."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Templates and appointment types must align.","Respect preferences.","Test automation.","Investigate configuration before workarounds."]}]'::jsonb,26,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

