insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='cliniko-for-virtual-assistants') and position=3),'creating-and-sending-cliniko-invoices','Creating and Sending Cliniko Invoices','Current Cliniko help recommends creating invoices from appointments when you want relevant patient, practitioner, date, and appointment details populated. A VA can support invoice administration if the practice has approved service and item rules.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand appointment-linked invoice workflow","Check invoice details before sending","Recognize permission and billing boundaries"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Current Cliniko help recommends creating invoices from appointments when you want relevant patient, practitioner, date, and appointment details populated. A VA can support invoice administration if the practice has approved service and item rules."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Invoices can be created from appointments or manually depending on workflow.","Patient, business, date, practitioner, and billable items need review.","The PDF a patient receives can include information that is not displayed the same way on the editing screen.","User permissions may restrict financial details.","Third-party billing may require different information."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm the appointment or service is ready to bill.","Open the approved invoice workflow.","Check patient, business, practitioner, date, and items.","Use only approved billable items and prices.","Preview patient-facing output where required.","Send through the approved channel.","Record outstanding or follow-up status."]},{"type":"callout","title":"Stay inside the role","text":"Do not invent billing items, change clinical service descriptions, alter provider numbers, or change prices merely to make an invoice work."},{"type":"callout","title":"Keep this current","text":"Cliniko changes over time. Verify the current official Cliniko Help before publishing or reviewing this lesson, especially appointment, reminder, invoice, payment, permission, and integration workflows."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Billing before service is confirmed","Assuming on-screen view equals patient PDF","Using the wrong business location","Adding an item from guesswork","Sending sensitive billing information to an unverified recipient"]},{"type":"scenario","title":"Practice scenario","text":"An invoice draft does not show a field on screen that the patient says appeared on their previous PDF. Explain how you verify the actual patient-facing output before changing settings."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Invoice from approved service data.","Check patient-facing output.","Respect financial permissions.","Escalate billing judgment."]}]'::jsonb,26,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='cliniko-for-virtual-assistants') and position=3),'payments-outstanding-invoices-and-xero-handoff','Payments, Outstanding Invoices, and Xero Handoff','Cliniko supports payment allocation, outstanding invoices, and Xero integration. The VA should help keep status accurate without forcing financial reconciliation or making accounting decisions.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Track payments correctly","Follow up outstanding invoices","Handle integration or reconciliation exceptions"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Cliniko supports payment allocation, outstanding invoices, and Xero integration. The VA should help keep status accurate without forcing financial reconciliation or making accounting decisions."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["A payment may need correct allocation to one or more invoices.","Outstanding reports support follow-up.","Third-party payments may differ from direct patient payments.","Xero integration can move finance data but does not remove review needs.","Write-offs and corrections should follow practice authority."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Check invoice and current payment status.","Record or allocate payments only under approved workflow.","Use outstanding-invoice reports or queues.","Send approved reminders after verifying no recent payment exists.","Flag allocation or sync discrepancies.","Route write-off, refund, tax, or accounting issues to the finance owner."]},{"type":"callout","title":"Stay inside the role","text":"Do not write off debt, change GST or accounting treatment, or force a payment allocation simply to clear the queue."},{"type":"callout","title":"Keep this current","text":"Cliniko changes over time. Verify the current official Cliniko Help before publishing or reviewing this lesson, especially appointment, reminder, invoice, payment, permission, and integration workflows."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Chasing a payment already received","Applying money to the wrong invoice","Treating an integration error as a reason to duplicate invoices","Creating unauthorized credits","Ignoring third-party payer context"]},{"type":"scenario","title":"Practice scenario","text":"Cliniko shows an invoice outstanding, but the practice bank account and Xero show a payment that may belong to it. Explain how you document and escalate the reconciliation instead of marking it paid from assumption."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Payment status needs evidence.","Verify before reminding.","Treat integrations as handoffs.","Keep accounting judgment with finance staff."]}]'::jsonb,26,2,false,1,null,null,now(),now())
