insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='cliniko-for-virtual-assistants') and position=4),'cliniko-admin-qa-and-composite-va-simulation','Cliniko Admin QA and Composite VA Simulation','Practice software can drift as practitioners, locations, appointment types, templates, integrations, and permissions change. The final simulation tests whether you can maintain the admin system safely.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Build a recurring Cliniko QA routine","Protect practice-wide settings","Apply patient, appointment, reminder, and billing workflows together"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Practice software can drift as practitioners, locations, appointment types, templates, integrations, and permissions change. The final simulation tests whether you can maintain the admin system safely."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["New users need least-privilege roles.","New appointment types may need reminder and billing configuration.","Templates should have an approval process.","Patient-facing outputs should be sampled after changes.","Software issues should be separated from practice-policy issues."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the fictional queue.","Resolve patient record duplication.","Correct an appointment workflow issue.","Investigate a reminder configuration problem.","Prepare an invoice and payment exception.","Identify an over-permissioned account.","Write the practice handoff."]},{"type":"callout","title":"Stay inside the role","text":"Do not experiment with live patient, billing, or practice-wide settings without an approved change process."},{"type":"callout","title":"Keep this current","text":"Cliniko changes over time. Verify the current official Cliniko Help before publishing or reviewing this lesson, especially appointment, reminder, invoice, payment, permission, and integration workflows."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Changing global settings during a live problem without documenting it","Giving full access to temporary staff","Adding appointment types without reminder setup","Editing templates directly with no approval","Assuming a software update preserved every workflow"]},{"type":"scenario","title":"Practice scenario","text":"A fictional physiotherapy clinic has duplicate patient records, one missing reminder, a rescheduled appointment, an invoice question, a payment mismatch, and an over-permissioned new staff account. Work through the safe Cliniko admin actions and escalations."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use Cliniko as the practice admin system.","Protect health data.","Keep automation and billing evidence-based.","Respect clinical and financial boundaries."]}]'::jsonb,26,1,false,1,null,null,now(),now())
